// Contabo-only transport for signed Binance operations. Fail closed on tunnel loss.
let contaboReady=false;
let contaboAgent:any=null;
async function contaboRequest(url:string,options:any={}):Promise<Response>{
 if(!contaboReady||!contaboAgent)throw Error("CONTABO_TUNNEL_NOT_READY");
 const https=await import("node:https");
 const parsed=new URL(url);
 return await new Promise<Response>((resolve,reject)=>{
  const req=https.request(parsed,{method:options.method||"GET",agent:contaboAgent,headers:options.headers||{},timeout:12000},res=>{
   const chunks:Uint8Array[]=[];let bytes=0;
   res.on("data",(chunk:Uint8Array)=>{bytes+=chunk.length;if(bytes>2000000){req.destroy(new Error("BINANCE_RESPONSE_TOO_LARGE"));return}chunks.push(chunk)});
   res.on("end",()=>resolve(new Response(Buffer.concat(chunks),{status:res.statusCode||502,headers:{"content-type":"application/json"}})));
  });
  req.on("timeout",()=>req.destroy(new Error("CONTABO_REQUEST_TIMEOUT")));
  req.on("error",reject);
  req.end();
 });
}
void(async()=>{
 if(Bun.env.ANS_CONTABO_TUNNEL_ENABLED!=="true"){console.error("ANS_CONTABO_DISABLED_FAIL_CLOSED");return}
 try{
  const {Client}=await import("ssh2");
  const {createServer}=await import("node:net");
  const {SocksProxyAgent}=await import("socks-proxy-agent");
  const host=Bun.env.ANS_CONTABO_SSH_HOST||"",username=Bun.env.ANS_CONTABO_SSH_USER||"";
  const privateKey=(Bun.env.ANS_CONTABO_SSH_PRIVATE_KEY||"").replace(/\\n/g,"\n");
  const port=Number(Bun.env.ANS_CONTABO_SSH_PORT||22);
  if(!host||!username||!privateKey||!Number.isInteger(port))throw Error("CONTABO_CONFIG_INCOMPLETE");
  const connect=()=>{
   const ssh=new Client();let listener:any=null;
   ssh.on("ready",()=>{
    listener=createServer((socket:any)=>{
     ssh.forwardOut("127.0.0.1",0,"127.0.0.1",1080,(error:any,stream:any)=>{
      if(error){socket.destroy();return}
      socket.pipe(stream).pipe(socket);
      socket.on("error",()=>stream.destroy());
      stream.on("error",()=>socket.destroy());
     });
    });
    listener.on("error",(err:any)=>console.error("ANS_CONTABO_LISTENER_ERROR "+String(err).slice(0,120)));
    listener.listen(1080,"127.0.0.1",()=>{
     contaboAgent=new SocksProxyAgent("socks5h://127.0.0.1:1080");
     contaboReady=true;
     console.log("ANS_CONTABO_V2_TUNNEL_READY");
    });
   });
   ssh.on("error",(err:any)=>{contaboReady=false;console.error("ANS_CONTABO_SSH_ERROR "+String(err).slice(0,120))});
   ssh.on("close",()=>{contaboReady=false;contaboAgent=null;if(listener)listener.close();setTimeout(connect,10000)});
   ssh.connect({host,port,username,privateKey,readyTimeout:45000,keepaliveInterval:30000,keepaliveCountMax:3});
  };
  connect();
 }catch(err){contaboReady=false;console.error("ANS_CONTABO_V2_INIT_ERROR "+String(err).slice(0,180))}
})();
