async function marketCloseProfit(symbol:string,expectedSide:string){
 const positions=await signedRead("/fapi/v2/positionRisk");
 const pos=positions.find((x:any)=>x.symbol===symbol&&x.positionSide===expectedSide&&Number(x.positionAmt)!==0);
 if(!pos)return{alreadyFlat:true,flatVerified:true};
 const qty=Number(pos.positionAmt);
 if((qty>0?"LONG":"SHORT")!==expectedSide)throw Error("PROFIT_MARKET_DIRECTION_CHANGED");
 const info=await cachedExchangeInfo();
 const sym=info.symbols.find((x:any)=>x.symbol===symbol);
 const lot=sym?.filters?.find((f:any)=>f.filterType==="MARKET_LOT_SIZE")||sym?.filters?.find((f:any)=>f.filterType==="LOT_SIZE");
 if(!lot)throw Error("PROFIT_MARKET_LOT_MISSING");
 const amount=roundDown(Math.abs(qty),lot.stepSize);
 if(!(Number(amount)>0))throw Error("PROFIT_MARKET_QUANTITY_INVALID");
 const order=await signedWrite("/fapi/v1/order",{symbol,side:qty>0?"SELL":"BUY",type:"MARKET",quantity:amount,positionSide:expectedSide,newOrderRespType:"RESULT"});
 const after=await signedRead("/fapi/v2/positionRisk");
 const remaining=after.find((x:any)=>x.symbol===symbol&&x.positionSide===expectedSide&&Number(x.positionAmt)!==0);
 return{orderId:order.orderId,status:order.status,flatVerified:!remaining,remainingQuantity:Number(remaining?.positionAmt||0)};
}
async function pollEmbeddedGuardian(){
 if(liveGuardBusy||!profitGuardRestored)return;
 liveGuardBusy=true;
 let changed=false;
 try{
  const positions=await signedRead("/fapi/v2/positionRisk");
  const openRaw=await signedRead("/fapi/v1/openAlgoOrders");
  const openOrders=Array.isArray(openRaw)?openRaw:openRaw?.orders||[];
  for(const p of positions){
   const symbol=String(p.symbol||""),qty=Number(p.positionAmt);
   if(!qty)continue;
   const side=qty>0?"LONG":"SHORT";
   const pnl=Number(p.unRealizedProfit??p.unrealizedProfit);
   if(!Number.isFinite(pnl))continue;
   let state=liveGuardPositions.get(symbol);
   if(!state||state.side!==side){
    state={peak:Math.max(0,pnl),closing:false,locked:0,side,lastSeenAt:Date.now()};
    liveGuardPositions.set(symbol,state);changed=true;
    console.log("ANS_LIVE_MARKET_PROFIT_TRACK_BEGIN "+JSON.stringify({symbol,side,initialPnl:pnl,priorPeakUnknown:true}));
   }
   if(state.closing)continue;
   const stops=openOrders.filter((a:any)=>a.symbol===symbol&&(a.type==="STOP_MARKET"||a.orderType==="STOP_MARKET")&&a.side===(qty>0?"SELL":"BUY")&&(!a.positionSide||a.positionSide===side));
   if(!stops.length)console.error("ANS_LIVE_MARKET_PROFIT_MISSING_EXCHANGE_SL "+JSON.stringify({symbol,side,unrealizedPnl:pnl}));
   if(pnl>state.peak){state.peak=pnl;changed=true}
   state.lastSeenAt=Date.now();changed=true;
   const signal=profitPreview(pnl,state.peak);
   if(signal.floorUsd>state.locked){state.locked=signal.floorUsd;changed=true;console.log("ANS_LIVE_MARKET_PROFIT_ARMED "+JSON.stringify({symbol,side,peak:state.peak,floor:signal.floorUsd,marketExitAt:signal.marketExitAtUsd}))}
   if(!signal.closeSignal)continue;
   state.closing=true;
   console.log("ANS_LIVE_MARKET_PROFIT_EXIT_SIGNAL "+JSON.stringify({symbol,side,peak:state.peak,currentPnl:pnl,floor:signal.floorUsd,marketExitAt:signal.marketExitAtUsd,mode:"MARKET_CLOSE_NO_PROFIT_STOP_UPDATE"}));
   try{
    const closed=await marketCloseProfit(symbol,side);
    if(!closed.flatVerified)throw Error("PROFIT_MARKET_CLOSE_NOT_FLAT");
    console.log("ANS_LIVE_MARKET_PROFIT_EXIT_CONFIRMED "+JSON.stringify({symbol,side,...closed,observedPnl:pnl,peak:state.peak,floor:signal.floorUsd}));
    liveGuardPositions.delete(symbol);changed=true;
   }catch(err){console.error("ANS_LIVE_MARKET_PROFIT_EXIT_FAILED "+JSON.stringify({symbol,error:String(err).slice(0,180)}));state.closing=false}
  }
  for(const symbol of liveGuardPositions.keys())if(!positions.some((p:any)=>p.symbol===symbol&&Number(p.positionAmt)!==0)){liveGuardPositions.delete(symbol);changed=true}
  if(changed)await saveProfitGuardState();
 }catch(err){console.error("ANS_LIVE_MARKET_PROFIT_POLL_ERROR "+String(err).slice(0,180))}
 finally{liveGuardBusy=false}
}
